drop function if exists platform.list_tenants_with_pending_messaging(int);
drop function if exists platform.list_tenants_with_pending_messaging(int, text[]);

create or replace function platform.list_tenants_with_pending_messaging(
  p_limit int default 100,
  p_modules text[] default null
)
returns table (
  tenant_id uuid,
  module_schema text,
  queue_type text,
  pending_count bigint,
  oldest_created_at timestamptz
)
language sql
security definer
set search_path = platform, pg_temp
as $$
  select
    stats.tenant_id,
    stats.module_schema,
    stats.queue_type,
    stats.pending_count,
    stats.oldest_pending_at as oldest_created_at
  from platform.messaging_backlog_stats stats
  where stats.pending_count > 0
    and stats.tenant_id is not null
    and stats.module_schema is not null
    and stats.queue_type is not null
    and (p_modules is null or stats.module_schema = any (p_modules))
  order by stats.oldest_pending_at asc
  limit greatest(p_limit, 1);
$$;

revoke all on function platform.list_tenants_with_pending_messaging(int, text[])
  from public, anon, authenticated;
grant execute on function platform.list_tenants_with_pending_messaging(int, text[])
  to service_role;
